using System.Net.Http.Json;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpServer;

// The SDK discovers this class via [McpServerToolType] and creates an
// instance per invocation. Constructor parameters are resolved from the
// host's DI container — here we receive IHttpClientFactory automatically.
[McpServerToolType]
public class WeatherTools(IHttpClientFactory httpFactory)
{
    // Each [McpServerTool] becomes a callable tool in the MCP protocol.
    // The Description is surfaced to LLMs so they know *when* to call it.
    [McpServerTool, Description("Get current weather for a location.")]
    public async Task<string> GetCurrentWeather(
        [Description("Latitude of the location")]  double latitude,
        [Description("Longitude of the location")] double longitude)
    {
        using var client = httpFactory.CreateClient("weather");

        var url = $"v1/forecast?latitude={latitude}&longitude={longitude}"
                + "&current=temperature_2m,wind_speed_10m";

        using var response = await client.GetAsync(url);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>();
        var current = json.GetProperty("current");

        var temp = current.GetProperty("temperature_2m").GetDouble();
        var wind = current.GetProperty("wind_speed_10m").GetDouble();

        return $"Temperature: {temp}°C, Wind: {wind} km/h";
    }

    [McpServerTool, Description("Get hourly temperature forecast for a location.")]
    public async Task<string> GetHourlyForecast(
        [Description("Latitude of the location")]  double latitude,
        [Description("Longitude of the location")] double longitude,
        [Description("Number of forecast hours (1-48)")] int hours = 24)
    {
        hours = Math.Clamp(hours, 1, 48);

        using var client = httpFactory.CreateClient("weather");

        var url = $"v1/forecast?latitude={latitude}&longitude={longitude}"
                + $"&hourly=temperature_2m&forecast_hours={hours}";

        using var response = await client.GetAsync(url);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>();
        var hourly = json.GetProperty("hourly");

        var times = hourly.GetProperty("time").EnumerateArray();
        var temps = hourly.GetProperty("temperature_2m").EnumerateArray();

        var lines = times.Zip(temps, (t, v) =>
            $"{t.GetString()}: {v.GetDouble()}°C");

        return string.Join('\n', lines);
    }
}

// Using System.ComponentModel for [Description] — the MCP SDK reads it
// from both parameters and methods.
using DescriptionAttribute = System.ComponentModel.DescriptionAttribute;

